insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cu', '/flags/history/cu-1868.svg', '1868-10-10', '1878-02-10', 'Drapeau de Céspedes (guerre de Dix Ans)', 'Céspedes flag (Ten Years'' War)', 'Hissé par Carlos Manuel de Céspedes à La Demajagua le 10 octobre 1868, au début de la guerre de Dix Ans. Il est aujourd''hui exposé à l''Assemblée nationale.', 'Raised by Carlos Manuel de Céspedes at La Demajagua on 10 October 1868, at the start of the Ten Years'' War. It is now displayed in the National Assembly.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('cu', '/flags/history/cu-1902.svg', '1902-05-20', '1906-04-24', 'République de Cuba (bleu ciel, 1902-1906)', 'Republic of Cuba (sky blue, 1902–1906)', 'À l''indépendance de 1902, le drapeau de Narciso López devient national dans une version au bleu ciel, avant qu''un décret de 1906 ne fixe un bleu plus foncé.', 'At independence in 1902, Narciso López''s flag became national in a sky-blue version, until a 1906 decree set a darker blue.');
